import React, { useState, useEffect, useCallback } from 'react';
import ReactFlow, {
  MiniMap,
  Controls,
  Background,
  addEdge,
  useNodesState,
  useEdgesState,
} from 'reactflow';
import 'reactflow/dist/style.css';
import { Box, Button, CssBaseline, Divider, Drawer, Typography, AppBar, Toolbar } from '@mui/material';

const drawerWidth = 400;

// Convert folder-file JSON to React Flow nodes & edges
function jsonToFlowNodesEdges(node, parentId = null, nodes = [], edges = [], pos = { x: 0, y: 0 }) {
  const id = parentId ? `${parentId}/${node.name}` : node.name;
  nodes.push({
    id,
    type: 'default',
    data: { label: node.name, nodeData: node, id },
    position: { x: pos.x, y: pos.y },
    style: {
      background: node.children.length ? '#90caf9' : '#fff59d',
      border: '1px solid #222',
      borderRadius: 5,
      padding: 10,
      width: 140,
      textAlign: 'center',
      cursor: 'pointer',
      fontWeight: 'bold',
      boxShadow: '2px 2px 8px rgba(0,0,0,0.3)',
      userSelect: 'none',
      whiteSpace: 'nowrap'
    }
  });
  if (parentId) {
    edges.push({ id: `${parentId}->${id}`, source: parentId, target: id, animated: true });
  }
  if (node.children) {
    node.children.forEach((child, index) => {
      jsonToFlowNodesEdges(child, id, nodes, edges, { x: pos.x + 180, y: pos.y + index * 100 });
    });
  }
  return { nodes, edges };
}

export default function App() {
  // React Flow state
  const [treeData, setTreeData] = useState(null);
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [selectedFileContent, setSelectedFileContent] = useState(null);
  const [selectedPath, setSelectedPath] = useState(null);

  // Load nodes and edges when treeData changes
  useEffect(() => {
    if (treeData) {
      const { nodes, edges } = jsonToFlowNodesEdges(treeData);
      setNodes(nodes);
      setEdges(edges);
      setSelectedFileContent(null);
      setSelectedPath(null);
    }
  }, [treeData, setNodes, setEdges]);

  // Upload and parse zip
  const uploadZip = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('repoZip', file);

    try {
      const res = await fetch('http://localhost:5000/upload', { method: 'POST', body: formData });
      if (res.ok) {
        const data = await res.json();
        setTreeData(data);
      } else {
        alert('Upload failed');
      }
    } catch {
      alert('Error fetching upload');
    }
  };

  // Node click: if file, fetch and show content; else clear content
  const onNodeClick = useCallback(
    async (event, node) => {
      if (node.data?.nodeData?.children.length === 0) {
        // File node
        try {
          const res = await fetch('http://localhost:5000/file-content', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ path: node.id }),
          });
          const json = await res.json();
          if (json.content) {
            setSelectedFileContent(json.content);
            setSelectedPath(node.id);
          } else {
            setSelectedFileContent('Failed to load file content');
            setSelectedPath(node.id);
          }
        } catch {
          setSelectedFileContent('Error fetching file content');
          setSelectedPath(node.id);
        }
      } else {
        // Folder node
        setSelectedFileContent(null);
        setSelectedPath(null);
      }
    },
    []
  );

  return (
    <Box sx={{ display: 'flex' }}>
      <CssBaseline />
      <AppBar position="fixed" sx={{ zIndex: (theme) => theme.zIndex.drawer + 1 }}>
        <Toolbar>
          <Typography variant="h6" noWrap component="div" sx={{ flexGrow: 1 }}>
            Code Repository Visualizer
          </Typography>
          <Button variant="contained" component="label">
            Upload ZIP
            <input hidden type="file" accept=".zip" onChange={uploadZip} />
          </Button>
        </Toolbar>
      </AppBar>

      <Drawer
        variant="persistent"
        anchor="right"
        open={Boolean(selectedFileContent)}
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          '& .MuiDrawer-paper': { width: drawerWidth, boxSizing: 'border-box', padding: 2 },
        }}
      >
        <Typography variant="h6" gutterBottom>
          {selectedPath || 'File Content'}
        </Typography>
        <Divider />
        <Box component="pre" sx={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word', marginTop: 2, height: '90vh', overflow: 'auto', fontFamily: 'monospace', fontSize: 14 }}>
          {selectedFileContent || 'Select a file node to see its content.'}
        </Box>
      </Drawer>

      <Box component="main" sx={{ flexGrow: 1, height: '100vh', mt: 8 }}>
        {treeData ? (
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onNodeClick={onNodeClick}
            fitView
            fitViewOptions={{ padding: 0.1 }}
          >
            <MiniMap />
            <Controls />
            <Background />
          </ReactFlow>
        ) : (
          <Typography variant="h5" sx={{ marginTop: 4, textAlign: 'center', color: '#888' }}>
            Upload a zip file to start visualizing
          </Typography>
        )}
      </Box>
    </Box>
  );
}
